const titulo = document.getElementById('titulo');
const itens = document.querySelectorAll('.item');
console.log(titulo.textContent, itens.length);

const itens = document.querySelectorAll('li');
const nomes = [];
itens.forEach((item) => nomes.push(item.textContent));
console.log(nomes.join(' | '));

const lista = document.getElementById('lista');
const item = document.createElement('li');
item.textContent = 'Novo item';
lista.appendChild(item);
console.log(lista.firstElementChild.tagName, lista.textContent);

const card = document.getElementById('card');
card.classList.add('ativo');
card.classList.remove('card');
card.classList.toggle('destaque');
console.log(card.classList.contains('card'), card.className);

const painel = document.getElementById('painel');
const primeiro = painel.classList.toggle('aberto');
const segundo = painel.classList.toggle('aberto');
console.log(primeiro, segundo, painel.className);

const botao = document.getElementById('btn');
botao.dataset.tema = 'escuro';
botao.setAttribute('data-tamanho', 'grande');
console.log(botao.dataset.tema, botao.getAttribute('data-tamanho'));

const botao = document.getElementById('contar');
let total = 0;
botao.addEventListener('click', () => {
  total += 1;
  botao.textContent = String(total);
});
botao.click();
botao.click();
console.log(botao.textContent);

const lista = document.getElementById('lista');
lista.addEventListener('click', (evento) => {
  console.log(evento.target.tagName, evento.currentTarget.id, evento.target.dataset.id);
});
lista.querySelector('[data-id="2"]').click();

const pai = document.getElementById('pai');
const filho = document.getElementById('filho');
const ordem = [];
pai.addEventListener('click', () => ordem.push('pai'));
filho.addEventListener('click', () => ordem.push('filho'));
filho.click();
console.log(ordem.join(' > '));

const lista = document.getElementById('lista');
lista.addEventListener('click', (evento) => {
  const botao = evento.target.closest('button[data-acao]');
  console.log(botao ? botao.dataset.acao : 'fora');
});
lista.querySelector('button').click();

const form = document.getElementById('form');
form.addEventListener('submit', (evento) => {
  evento.preventDefault();
  console.log(evento.defaultPrevented);
});
form.dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));

const lista = document.getElementById('lista');
document.getElementById('app').innerHTML = '<ul id="lista"></ul>';
console.log(lista === null);
